"""JUnit parsing for pytest and cargo-nextest reports (real samples).

tests/data/junit/
* pytest-mixed.xml - generated by pytest 9.1.1 (`--junitxml`) on a 5-test sample
  module: 2 passed, 1 failed, 1 errored (fixture setup), 1 skipped.
* pytest-empty.xml - generated by pytest 9.1.1 in a directory with no tests (exit 5).
* nextest-fixture-project.xml - verbatim copy of cargo-nextest's own generated
  fixture ``fixtures/fixture-project-junit.xml`` (nextest-rs/nextest @ 0489fa7,
  MIT OR Apache-2.0): 3 tests, one failing with retries (<rerunFailure>) and one
  flaky test that eventually passed (<flakyFailure> children, no <failure>).
  It was NOT produced on this box: Rust is not compiled here (shared 2.5 GB
  docker VM), so the upstream generated sample is used instead of a hand-written one.
"""

from __future__ import annotations

from pathlib import Path

import pytest

from services.junit_parser import MAX_MESSAGE_CHARS, JUnitParseError, parse_junit

DATA = Path(__file__).resolve().parent.parent / "data" / "junit"


def _read(name: str) -> str:
    return (DATA / name).read_text()


def test_pytest_mixed_counts_and_cases() -> None:
    parsed = parse_junit(_read("pytest-mixed.xml"))
    by_name = {c.name: c for c in parsed.cases}
    assert parsed.count("passed") == 2
    assert parsed.count("failed") == 1
    assert parsed.count("errored") == 1
    assert parsed.count("skipped") == 1
    assert len(parsed.cases) == 5
    assert by_name["test_sample::test_add_passes"].status == "passed"
    fail = by_name["test_sample::test_add_fails"]
    assert fail.status == "failed"
    assert fail.message and "assert 4 == 5" in fail.message
    err = by_name["test_sample::test_errors_in_setup"]
    assert err.status == "errored"
    assert err.message and "fixture setup exploded" in err.message
    assert by_name["test_sample::test_skipped"].status == "skipped"
    assert by_name["test_sample.TestGroup::test_in_class"].status == "passed"
    assert parsed.duration == pytest.approx(0.024)


def test_pytest_empty_report_has_no_cases() -> None:
    parsed = parse_junit(_read("pytest-empty.xml"))
    assert parsed.cases == []


def test_nextest_fixture_counts_flaky_as_passed_and_retries_as_one_failure() -> None:
    parsed = parse_junit(_read("nextest-fixture-project.xml"))
    by_name = {c.name: c for c in parsed.cases}
    assert set(by_name) == {
        "fixture-project::basic::test_cwd",
        "fixture-project::basic::test_failure_assert",
        "fixture-project::basic::test_flaky_mod_4",
    }
    assert by_name["fixture-project::basic::test_cwd"].status == "passed"
    failed = by_name["fixture-project::basic::test_failure_assert"]
    assert failed.status == "failed"
    assert failed.message and "assertion `left == right` failed" in failed.message
    # flakyFailure children only: the test eventually passed.
    assert by_name["fixture-project::basic::test_flaky_mod_4"].status == "passed"
    assert parsed.count("failed") == 1
    assert parsed.duration == pytest.approx(0.023)


def test_bare_testsuite_root_and_suite_time_fallback() -> None:
    xml = (
        '<testsuite name="x" tests="2" time="1.5">'
        '<testcase name="a" time="1.0"/>'
        '<testcase name="b"><skipped message="ignored"/></testcase>'
        "</testsuite>"
    )
    parsed = parse_junit(xml)
    assert [(c.name, c.status) for c in parsed.cases] == [("a", "passed"), ("b", "skipped")]
    assert parsed.cases[1].message == "ignored"
    assert parsed.duration == pytest.approx(1.5)


def test_testsuites_without_time_sums_suites() -> None:
    xml = (
        "<testsuites>"
        '<testsuite name="s1" time="1.0"><testcase name="a"/></testsuite>'
        '<testsuite name="s2" time="2.0"><testcase name="b"/></testsuite>'
        "</testsuites>"
    )
    assert parse_junit(xml).duration == pytest.approx(3.0)


def test_no_times_at_all_gives_none() -> None:
    parsed = parse_junit(
        '<testsuites><testsuite name="s"><testcase name="a" time="x"/></testsuite></testsuites>'
    )
    assert parsed.duration is None
    assert parsed.cases[0].duration is None


def test_message_is_capped() -> None:
    xml = f'<testsuite><testcase name="a"><failure>{"x" * (MAX_MESSAGE_CHARS + 50)}</failure></testcase></testsuite>'
    msg = parse_junit(xml).cases[0].message
    assert msg is not None and len(msg) == MAX_MESSAGE_CHARS


@pytest.mark.parametrize(
    "xml",
    [
        "not xml",
        "<html><body/></html>",
        # entity expansion is refused (defusedxml), not evaluated
        '<?xml version="1.0"?><!DOCTYPE t [<!ENTITY a "aaaa">]><testsuite><testcase name="&a;"/></testsuite>',
    ],
)
def test_rejects_non_junit(xml: str) -> None:
    with pytest.raises(JUnitParseError):
        parse_junit(xml)
